-- SANDBOX/DEMO ONLY. Idempotent course seed; no deletes, personal answers or email.
begin;
set local statement_timeout='30s';
do $$declare u uuid;c uuid;p uuid;s jsonb:='{}';a jsonb;t jsonb;r jsonb;items jsonb:='[]';id uuid;v uuid;content jsonb;begin
 select pr.id into u from public.profiles pr where email='demo@expo-proffdok.no' and approved and not coalesce(deactivated,false);
 select project.company_scope_id,project.id into c,p from public.projects project where data->'project'->>'demoSuiteKey'='golden-demo-v1' and title='DEMO – HOVED – Badrenovering i arbeid';
 if u is null or c is null or not exists(select 1 from public.sales_company_memberships where user_id=u and company_id=c and workspace_role='firmaadmin') then raise exception 'Dedicated demo user/company/project required';end if;
 if not exists(select 1 from kshms_private.email_worker_settings where singleton and not enabled) then raise exception 'Sandbox email must be disabled';end if;
 if exists(select 1 from public.demo_sandbox_snapshots where snapshot_key='people-course-v1') then return;end if;
 perform set_config('request.jwt.claim.sub',u::text,true);
 if public.current_active_company_scope_id() is distinct from c then raise exception 'Select Expo Proffsenter before course seed';end if;
 s:=jsonb_build_object('version',1,'company_id',c,'user_id',u);
 for content in select value from jsonb_array_elements('[{"title":"DEMO – Årlig medarbeidersamtale","kind":"annual","intro":"Fiktivt kurseksempel. Forbered noen korte refleksjoner. I møtet går medarbeider og leder gjennom temaene sammen og avtaler eventuell oppfølging.","questions":[{"id":"c0cc152a-e7fa-4fc2-a209-a622001363d4","topic":"Trivsel","prompt":"Hva fungerer godt i arbeidshverdagen, og hva ønsker du å endre?","phase":"preparation","required":true},{"id":"3ffcc2cd-da6d-4393-ba21-ec3343467435","topic":"Arbeidsbelastning","prompt":"Hvordan opplever du arbeidsmengden og balansen mellom oppgaver og tid?","phase":"preparation","required":true},{"id":"f1f27560-ec6d-4f72-9cc6-c00895dfeb57","topic":"Samarbeid","prompt":"Hvordan fungerer samarbeidet, og hva kan vi gjøre bedre?","phase":"preparation","required":true},{"id":"a1f26819-3106-4ca6-9073-2f026e04904f","topic":"Arbeidsmiljø og sikkerhet","prompt":"Hva kan gjøre arbeidshverdagen tryggere og mer inkluderende?","phase":"preparation","required":true},{"id":"6193fbc9-23ff-4639-8d3d-8bf26d6cd718","topic":"Kompetanse","prompt":"Hva ønsker du å lære eller få mer øvelse i?","phase":"preparation","required":true},{"id":"58f381e6-90e9-4aee-9b58-a90169d6110e","topic":"Lederstøtte","prompt":"Hva trenger du fra lederen og bedriften for å lykkes?","phase":"preparation","required":true},{"id":"6b5abb22-a6ef-4566-a0dd-e308e2222b1a","topic":"Mål","prompt":"Hvilke konkrete mål ønsker du å jobbe mot?","phase":"preparation","required":true},{"id":"5c79a68b-e768-47c5-8f0e-57f6cd76e95a","topic":"Felles oppsummering","prompt":"Hva vil medarbeider og leder ta med seg fra samtalen?","phase":"meeting","required":true},{"id":"83232c5c-1841-4dc9-8abf-91190d2362c1","topic":"Avtaler og tiltak","prompt":"Trengs oppfølging? Avtal hva som skal gjøres, hvem som har ansvar, frist og neste oppfølging.","phase":"meeting","required":false},{"id":"cbd76ec5-4c94-43c5-884e-1ecbfb91e5fc","topic":"Egne kommentarer","prompt":"Er det ulike syn eller kommentarer som skal følge referatet?","phase":"meeting","required":false}]},{"title":"DEMO – Prøvetidssamtale","kind":"probation","intro":"Fiktivt kurseksempel. Se på forventninger, opplæring og støtte. Bruk konkrete eksempler og avtal hva som hjelper medarbeideren videre.","questions":[{"id":"97d471e6-8763-4ad6-930e-2f7d4620ef29","topic":"Forventninger","prompt":"Er oppgavene og forventningene tydelige?","phase":"preparation","required":true},{"id":"1a4a8f84-44db-4388-91f2-ed3512225099","topic":"Opplæring","prompt":"Hvilken opplæring har fungert, og hva mangler du?","phase":"preparation","required":true},{"id":"aed3aea9-b05e-458d-ab81-5e95343d941c","topic":"Støtte og samarbeid","prompt":"Hvem kan hjelpe deg, og hva trenger du fra leder eller kolleger?","phase":"preparation","required":true},{"id":"13e9b870-cd62-4f08-aded-d75a00bee71d","topic":"Arbeidshverdag","prompt":"Hva fungerer godt, og hvilke oppgaver er krevende?","phase":"preparation","required":true},{"id":"2d3a05d6-eb1b-44ec-aceb-5410a64db623","topic":"Videre utvikling","prompt":"Hva vil du øve på eller lære fremover?","phase":"preparation","required":true},{"id":"398f6f27-8237-41e5-a887-909da4adb459","topic":"Felles oppsummering","prompt":"Hva vil medarbeider og leder ta med seg fra samtalen?","phase":"meeting","required":true},{"id":"e4a9d7d9-bfe0-4077-99d5-84ad27e6d2ca","topic":"Avtaler og tiltak","prompt":"Trengs oppfølging? Avtal hva som skal gjøres, hvem som har ansvar, frist og neste oppfølging.","phase":"meeting","required":false},{"id":"246b572d-347d-47d4-a2a9-87634a13c6de","topic":"Egne kommentarer","prompt":"Er det ulike syn eller kommentarer som skal følge referatet?","phase":"meeting","required":false}]},{"title":"DEMO – Sykefraværsoppfølging","kind":"sickleave","intro":"Fiktivt kurseksempel. Snakk om arbeid og muligheter for tilrettelegging. Forbered egne innspill, og lag planen sammen. Ikke ta med diagnose eller medisinske opplysninger. Malen er et utgangspunkt; den er ikke en innsendt oppfølgingsplan.","questions":[{"id":"c5f39f13-1ea6-4627-845e-344b28383ca1","topic":"Kontakt","prompt":"Hvordan ønsker du at vi holder kontakten, og hva gjør kontakten nyttig for deg?","phase":"preparation","required":true},{"id":"dd3370e2-d82a-4a1f-a17f-43140fc05574","topic":"Arbeidsoppgaver","prompt":"Hvilke oppgaver kan du utføre eller prøve nå? Hvilke oppgaver er vanskelige?","phase":"preparation","required":true},{"id":"e85641d5-ef72-495d-a5eb-0de49b34bc0b","topic":"Muligheter","prompt":"Kan andre oppgaver, hjelpemidler, arbeid med en kollega eller endret arbeidstid hjelpe?","phase":"preparation","required":true},{"id":"cfe57b0e-cbeb-4d8c-a572-0bec364ea789","topic":"Støtte","prompt":"Hva trenger du fra leder og bedriften for å komme tilbake eller fortsette i arbeid?","phase":"preparation","required":true},{"id":"d00c1ef8-0a8a-45eb-9df1-1f11c2f418b8","topic":"Kontaktavtale","prompt":"Avtal kontaktform, hvem som tar kontakt og når dere snakker sammen neste gang.","phase":"meeting","required":true},{"id":"62277cb1-179e-4f9c-b68b-d5962383e2b3","topic":"Tilrettelegging","prompt":"Vurder firmaets muligheter sammen. Hva skal prøves, og hva er foreløpig ikke mulig? Forklar vurderingen.","phase":"meeting","required":true},{"id":"7be029fd-8662-48d2-ac34-d92dd94405c7","topic":"Felles oppfølgingsplan","prompt":"Oppsummer aktuelle oppgaver, hva som kan prøves og planen videre. Se over innholdet sammen.","phase":"meeting","required":true},{"id":"98102747-7bfa-4976-8140-4c2d3f68fa19","topic":"Tiltak og oppfølging","prompt":"For hvert avtalt tiltak: hva skal gjøres, hvem har ansvar, hvilken frist gjelder og når vurderer dere resultatet?","phase":"meeting","required":true},{"id":"4fbc167f-2be7-4738-b424-50ae2b2f6182","topic":"Behov for bistand","prompt":"Trenger dere hjelp fra bedriftshelsetjenesten, sykmelder eller NAV? Avtal hvem som følger opp.","phase":"meeting","required":false},{"id":"c6447a57-d021-492c-b2f5-9a76dc93c778","topic":"Tilbake i arbeid","prompt":"Hva kan være et godt neste steg mot arbeid? Avtal eventuell opptrapping og ny gjennomgang.","phase":"meeting","required":false},{"id":"b86835b7-8521-4ac4-baf9-f085ae8b6d10","topic":"Kommentarer og uenighet","prompt":"Hvilke egne kommentarer eller ulike syn skal følge planen? Begge skal få lese og bekrefte sin gjennomgang.","phase":"meeting","required":false}]}]'::jsonb) loop
  id:=gen_random_uuid();r:=public.hr_template_save(c,id,0,content,false);
  items:=items||jsonb_build_array(jsonb_build_object('id',id,'content',r#>'{version,content}'));
 end loop;s:=s||jsonb_build_object('templates',items);
 id:=gen_random_uuid();r:=public.kshms_checklist_command(c,'publish',gen_random_uuid(),jsonb_build_object('id',id,'revision',0,'content','{"title":"DEMO – Kontroll før innbygging","trade":"Rørlegger","instructions":"Fiktiv firmamal for kurs. Vurder den konkrete jobben; eksempelet bekrefter ingen utført kontroll.","points":[{"id":"447e44ab-95ea-4c28-b0f0-3a1520b8cf11","title":"Kontroll før innbygging","guidance":"Kontroller at rørføring, festing og tilgjengelighet er dokumentert.","image_required":false,"comment_required":true},{"id":"211d7488-6d0a-448d-ab2d-ca40769848e6","title":"Tetthet og prøving","guidance":"Avklar prøvemetode og dokumenter resultatet før innbygging.","image_required":false,"comment_required":true},{"id":"1354328f-1479-4d38-ae45-a278ed8711fe","title":"Bilder og sporbarhet","guidance":"Ta bilder av utførelsen og noter produkt-/systemgrunnlaget.","image_required":false,"comment_required":true}]}'::jsonb));
 s:=s||jsonb_build_object('checklist',jsonb_build_object('id',id,'version_id',r#>'{version,id}','content',r#>'{version,content}'));
 id:=gen_random_uuid();content:='{"title":"DEMO – Bytte rør og sanitær på HOVED","workplace":"Fiktivt bad i DEMO – HOVED","project_reference":"KURS-HOVED","task":"Fiktivt kurs: planlegg demontering og montering av rør og sanitær. Andre fag og kunde skal ikke gå inn i arbeidsområdet.","planned_on":"2026-10-20","reviewed_on":"","routines":"Slå opp relevante firmarutiner for sikring, arbeidsutstyr og beredskap.","equipment":"Avklart håndverktøy og transporthjelpemidler. Kontroll og opplæring må avklares før arbeidet.","ppe":"Vurder øyevern, hansker og vernefottøy etter farene og valgte tiltak.","emergency":"Kursoppgave: avklar kontaktperson, førstehjelpsutstyr og møtested for hjelp.","stop_conditions":"Stans ved uavklart energi/trykk, ustabilt underlag eller manglende avsperring. Vurder jobben på nytt.","communication":"Planlagt felles gjennomgang av arbeidstrinn og tiltak. Gjennomgangen er ikke utført i dette eksemplet.","steps":[{"id":"b57ae9a2-4248-4c47-b4ce-2df10b91b64e","activity":"Sikre arbeidssted og stenge vann","hazard":"Uavklart trykk eller personer i området","consequence":"Personskade eller vannskade","measures":"Avklar avstenging, trykkavlastning og avsperring","owner":"Fiktiv arbeidsleder","check":"Kontroller avstenging og fri adkomst før start"},{"id":"d4d152a9-a0f2-45ec-a9ed-42c933ca2e50","activity":"Demontere og transportere sanitær","hazard":"Tunge løft og skarpe kanter","consequence":"Belastningsskade eller kutt","measures":"Planlegg løftet, bemanning og hjelpemidler","owner":"Fiktiv rørlegger","check":"Kontroller løfterute og utstyr"},{"id":"ae67542f-6d1a-4b00-b2b6-234c2162568c","activity":"Montere og kontrollere","hazard":"Utetthet eller feil før innbygging","consequence":"Skade på bygg og nytt utstyr","measures":"Kontroller montasje, prøving og dokumentasjon før innbygging","owner":"Fiktiv rørlegger","check":"Dokumenter prøving og bilder før innbygging"}],"participants":[{"id":"97d90e03-d205-4c33-ad63-a5eaa8dfb4ff","name":"Fiktiv arbeidsleder","role":"Arbeidsleder","company":"Demofirma","involvement":"Kursrolle – gjennomgangen må utføres og beskrives."},{"id":"a6fe988a-3545-4d8d-b726-d0a620e3a477","name":"Fiktiv rørlegger","role":"Utførende","company":"Demofirma","involvement":"Kursrolle – vurder arbeidstrinn og tiltak sammen."}],"photos":[]}'::jsonb||jsonb_build_object('leader_id',u);
 r:=public.kshms_sja_command(c,'save',gen_random_uuid(),jsonb_build_object('id',id,'revision',0,'project_id',p,'content',content));
 s:=s||jsonb_build_object('sja',jsonb_build_object('id',id,'project_id',p,'content',r#>'{sja,content}'));
 items:='[]';for a in select value from jsonb_array_elements('[{"kind":"round","content":{"workplace":"Fiktivt bad i DEMO – HOVED","planned_on":"2026-10-20","participants":"Fiktiv arbeidsleder og rørlegger. Eksempelet er ikke en gjennomført kontroll.","review":"Avtal tiltak, ansvar og frister under kurset.","basis":"","reference":"KURS-HOVED","routines":"Velg relevante firmarutiner.","acceptance":{"low_max":4,"medium_max":12,"description":"Avklar kriterier og behov for stans før bruk.","confirmed":false},"risks":[],"points":[{"id":"a1d68742-04bb-4e0a-a028-95413382c6de","title":"Adkomst og rømningsvei","guidance":"Se etter hindringer og avklar fri vei.","image_required":false,"comment_required":true},{"id":"6564bac2-8ce8-44bd-92c7-dd979d6bb97b","title":"Arbeidsutstyr","guidance":"Kontroller egnethet, tilstand og nødvendig opplæring.","image_required":false,"comment_required":true},{"id":"130208ed-756b-4c51-b662-294e77e25fa4","title":"Samordning med andre fag","guidance":"Avklar avgrensning og hvem som arbeider i området.","image_required":false,"comment_required":true}],"answers":{},"title":"DEMO – Vernerunde før oppstart"}},{"kind":"risk","content":{"workplace":"Fiktivt bad i DEMO – HOVED","planned_on":"2026-10-20","participants":"Fiktiv arbeidsleder og rørlegger. Eksempelet er ikke en gjennomført kontroll.","review":"Avtal tiltak, ansvar og frister under kurset.","basis":"Fiktiv kursvurdering av personskade ved arbeid og transport i et lite bad. Vurder forholdene på stedet.","reference":"KURS-HOVED","routines":"Velg relevante firmarutiner.","acceptance":{"low_max":4,"medium_max":12,"description":"Avklar kriterier og behov for stans før bruk.","confirmed":false},"risks":[{"id":"c8cd3f3f-6d39-4b7f-ba8b-20049469c722","activity":"Transportere sanitærutstyr ut av badet","hazard":"Tunge løft og trang adkomst","consequence":"Belastningsskade eller klemskade","existing_measures":"Ryddet adkomst skal kontrolleres før start.","planned_measures":"Planlegg bemanning og egnede transporthjelpemidler.","due_on":"2026-10-20","probability_before":4,"consequence_before":3,"probability_after":2,"consequence_after":2,"follow_up":"Kontroller tiltakene før arbeidet. Etterverdiene er foreløpige anslag.","effect_status":"planned","verified_on":"","decision":"needs_action","reason":"Tiltakenes virkning er ikke kontrollert i kurseksemplet.","photos":[]}],"points":[],"answers":{},"title":"DEMO – Risiko ved demontering og transport"}}]'::jsonb) loop
  id:=gen_random_uuid();content:=a->'content'||jsonb_build_object('responsible_id',u);
  if a->>'kind'='risk' then content:=jsonb_set(content,'{risks,0,owner_id}',to_jsonb(u));end if;
  r:=public.kshms_execution_command(c,'save',gen_random_uuid(),jsonb_build_object('id',id,'kind',a->>'kind','revision',0,'project_id',p,'template_version_id',null,'content',content));
  r:=public.kshms_execution_detail(c,id);
  items:=items||jsonb_build_array(jsonb_build_object('id',id,'kind',a->>'kind','project_id',p,'template_version_id',null,'content',r#>'{record,content}'));
 end loop;s:=s||jsonb_build_object('executions',items);
 content:=jsonb_build_object('title','DEMO – RUH: utstyr i rømningsvei','event','Fiktivt kurseksempel: transportutstyr sto i planlagt rømningsvei før oppstart. Ingen reell hendelse er registrert.','category','ruh','immediate_action','Kursøvelse: avklar sikring og fri rømningsvei før arbeidet starter.','responsible_id',u,'handler_id',u,'due_on','2026-10-20','source_kind','company','project_id',p);
 r:=public.kshms_deviation_command(c,'create',content||jsonb_build_object('request_id',gen_random_uuid()));
 s:=s||jsonb_build_object('deviation',jsonb_build_object('id',r->'id','content',content));
 insert into public.demo_sandbox_snapshots(snapshot_key,payload,updated_at,updated_by) values('people-course-v1',s,now(),u);
end$$;
commit;
